(function () {
  'use strict';
  var root = document.documentElement;
  var toggle = document.getElementById('navToggle');
  var menu = document.getElementById('navMenu');
  var mode = document.getElementById('mode-toggle');
  var state = document.getElementById('mode-state');

  function setMenu(open) {
    if (!toggle || !menu) return;
    toggle.setAttribute('aria-expanded', String(open));
    menu.setAttribute('data-open', String(open));
  }

  if (toggle && menu) {
    setMenu(false);
    toggle.addEventListener('click', function () {
      setMenu(toggle.getAttribute('aria-expanded') !== 'true');
    });
    menu.addEventListener('click', function (event) {
      if (event.target.closest('a')) setMenu(false);
    });
    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && toggle.getAttribute('aria-expanded') === 'true') {
        setMenu(false);
        toggle.focus();
      }
    });
    document.addEventListener('click', function (event) {
      if (!menu.contains(event.target) && !toggle.contains(event.target)) setMenu(false);
    });
  }

  if (mode && state) {
    var order = ['system', 'light', 'dark'];
    var labels = {
      system: 'System',
      light: (mode.dataset && mode.dataset.labelLight) || 'Light',
      dark: (mode.dataset && mode.dataset.labelDark) || 'Dark'
    };
    function current() {
      var value = root.getAttribute('data-theme');
      return value === 'light' || value === 'dark' ? value : 'system';
    }
    function apply(value) {
      if (value === 'system') {
        root.removeAttribute('data-theme');
        try { localStorage.removeItem('theme'); } catch (error) { /* no-op */ }
      } else {
        root.setAttribute('data-theme', value);
        try { localStorage.setItem('theme', value); } catch (error) { /* no-op */ }
      }
      state.textContent = labels[value];
    }
    state.textContent = labels[current()];
    mode.addEventListener('click', function () {
      apply(order[(order.indexOf(current()) + 1) % order.length]);
    });
  }

  /* Dock search button into header slot without inline style mutations */
  function dockSearchButton() {
    var searchSlot = document.querySelector('[data-ssg-search]');
    var searchButton = document.getElementById('ssg-search-btn');
    if (searchSlot && searchButton) {
      searchSlot.replaceWith(searchButton);
    } else if (searchSlot && typeof MutationObserver === 'function') {
      var searchObserver = new MutationObserver(function () {
        var btn = document.getElementById('ssg-search-btn');
        if (btn) {
          searchSlot.replaceWith(btn);
          searchObserver.disconnect();
        }
      });
      searchObserver.observe(document.body, { childList: true, subtree: true });
    }
  }
  dockSearchButton();

  /* FAQ Accordion toggle */
  var faqQuestions = document.querySelectorAll('.faq-question');
  faqQuestions.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var item = btn.closest('.faq-item');
      var expanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!expanded));
      if (item) {
        item.classList.toggle('is-open', !expanded);
      }
    });
  });

  /* Interactive Cryptographic Engine with the full 7,776-word EFF Diceware list */
  /* wordlist-codec:start
     The full 7,776-word EFF Diceware list, packed so it ships inside this
     file (zero network requests) at roughly a fifth of the plain list's
     62 KB, and about half of what the plain list costs even after HTTP
     compression.

     WORDS_PACKED is generated by `node scripts/diceware-wordlist.mjs --write jspassgen`
     from themes/jspassgen/wordlist/eff_large_wordlist.txt; never edit it by
     hand. `make check-wordlist` decodes it and fails unless the result is
     byte-identical to that file, in the same order, so dice index N still
     maps to word N.

     How it is packed: the list is sorted, so each word is stored as the
     length of the prefix it shares with the previous word plus the letters
     that follow. Each of those symbols is arithmetic-coded with an adaptive
     model that blends the letter counts seen after the last zero to four
     letters (Witten-Bell interpolation), and letters that sorting rules out
     are never given any probability. Only + - * / and Math.floor are used
     on the probabilities, so every browser decodes the same bits. */
  var WORD_ALPHABET = "-abcdefghijklmnopqrstuvwxyz";
  var WORD_SYMBOLS = WORD_ALPHABET.length + 1; /* symbol 0 ends a word */
  var WORD_PREFIXES = 16;
  var WORD_ORDER = 4;
  var WORD_BLEND = 3;
  var WORD_SCALE = 65536;
  var WORDLIST_SIZE = 7776;
  var WORDS_PACKED = "";

  /* One scratch buffer, reused: wordFrequencies runs for every symbol. */
  var wordProbabilities = new Float64Array(Math.max(WORD_SYMBOLS, WORD_PREFIXES));

  /* Integer frequencies for symbols lo..hi-1; everything else gets 0. */
  function wordFrequencies(contexts, size, lo, hi) {
    var prob = wordProbabilities;
    var j;
    for (j = 0; j < size; j++) prob[j] = 1 / size;
    for (var k = 0; k < contexts.length; k++) {
      var entry = contexts[k];
      if (!entry.seen) continue;
      var weight = entry.seen / (entry.seen + WORD_BLEND * entry.distinct);
      for (j = 0; j < size; j++) {
        prob[j] = weight * entry.counts[j] / entry.seen + (1 - weight) * prob[j];
      }
    }
    var freq = new Array(size);
    for (j = 0; j < size; j++) {
      freq[j] = j >= lo && j < hi ? Math.floor(prob[j] * WORD_SCALE) + 1 : 0;
    }
    return freq;
  }

  function learnWordSymbol(contexts, symbol) {
    for (var k = 0; k < contexts.length; k++) {
      var entry = contexts[k];
      if (!entry.counts[symbol]) entry.distinct++;
      entry.counts[symbol]++;
      entry.seen++;
    }
  }

  /* The contexts a symbol is predicted from: the shared-prefix length after
     the previous one, and each letter after its last 0 to WORD_ORDER letters. */
  function createWordModel() {
    var tables = new Map();

    function table(key, size) {
      var entry = tables.get(key);
      if (!entry) {
        entry = { counts: new Uint32Array(size), seen: 0, distinct: 0 };
        tables.set(key, entry);
      }
      return entry;
    }

    return {
      prefix: function (previousShared) {
        return [table("P", WORD_PREFIXES), table("P" + previousShared, WORD_PREFIXES)];
      },
      letters: function (word, previous, shared) {
        var at = word.length;
        var contexts = [];
        for (var k = 0; k <= WORD_ORDER && k <= at + 1; k++) {
          contexts.push(table(k + ":" + (k <= at ? word.slice(at - k) : "^" + word), WORD_SYMBOLS));
        }
        if (at === shared) {
          contexts.push(table("F" + previous.charAt(at) + ":" + word.slice(-1), WORD_SYMBOLS));
        }
        return contexts;
      }
    };
  }

  /* Sorted order rules out some letters: the first new letter must sort
     after the previous word's letter at that position, and a word cannot
     end where it would equal or precede the previous word. */
  function lowestLetter(word, previous, shared) {
    if (word.length !== shared) return 0;
    if (shared < previous.length) return WORD_ALPHABET.indexOf(previous.charAt(shared)) + 2;
    return 1;
  }

  /* Rebuilds the list one symbol at a time. `next(freq)` returns the symbol
     to take: the decoder reads it from the bits, the encoder in
     scripts/diceware-wordlist.mjs supplies it from the plain list. */
  function walkWordlist(count, next) {
    var model = createWordModel();
    var words = [];
    var previous = "";
    var previousShared = 0;
    for (var n = 0; n < count; n++) {
      var prefixContexts = model.prefix(previousShared);
      var shared = next(wordFrequencies(prefixContexts, WORD_PREFIXES, 0, previous.length + 1));
      learnWordSymbol(prefixContexts, shared);
      var word = previous.slice(0, shared);
      for (;;) {
        var contexts = model.letters(word, previous, shared);
        var symbol = next(wordFrequencies(contexts, WORD_SYMBOLS, lowestLetter(word, previous, shared), WORD_SYMBOLS));
        learnWordSymbol(contexts, symbol);
        if (symbol === 0) break;
        word += WORD_ALPHABET.charAt(symbol - 1);
      }
      words.push(word);
      previous = word;
      previousShared = shared;
    }
    return words;
  }

  var CODER_TOP = 0x80000000;
  var CODER_HALF = 0x40000000;
  var CODER_QUARTER = 0x20000000;

  /* How far to slide the interval before doubling it: 0 or HALF when its
     top bit is settled, QUARTER when it straddles the middle, -1 when no
     doubling is due. The encoder shares this, so both stay in step. */
  function renormShift(low, high) {
    if (high < CODER_HALF) return 0;
    if (low >= CODER_HALF) return CODER_HALF;
    if (low >= CODER_QUARTER && high < CODER_HALF + CODER_QUARTER) return CODER_QUARTER;
    return -1;
  }

  /* Classic integer arithmetic decoder (31-bit interval). Products stay
     below 2^52, so plain numbers are exact. */
  function createSymbolReader(packed) {
    var bytes = atob(packed);
    var position = 0;
    function bit() {
      var index = position >> 3;
      var value = index < bytes.length ? (bytes.charCodeAt(index) >> (7 - (position & 7))) & 1 : 0;
      position++;
      return value;
    }
    var low = 0;
    var high = CODER_TOP - 1;
    var value = 0;
    for (var i = 0; i < 31; i++) value = value * 2 + bit();

    return function next(freq) {
      var total = 0;
      var s;
      for (s = 0; s < freq.length; s++) total += freq[s];
      var range = high - low + 1;
      var target = Math.floor(((value - low + 1) * total - 1) / range);
      var cumulative = 0;
      s = 0;
      while (cumulative + freq[s] <= target) cumulative += freq[s++];
      high = low + Math.floor(range * (cumulative + freq[s]) / total) - 1;
      low = low + Math.floor(range * cumulative / total);
      for (var shift = renormShift(low, high); shift >= 0; shift = renormShift(low, high)) {
        low = (low - shift) * 2;
        high = (high - shift) * 2 + 1;
        value = (value - shift) * 2 + bit();
      }
      return s;
    };
  }

  var dicewareWords = null;
  /* Decoded on first use rather than at load, so the page's main thread
     does no wordlist work unless a passphrase is asked for. */
  function getDicewareWords() {
    if (!dicewareWords) dicewareWords = walkWordlist(WORDLIST_SIZE, createSymbolReader(WORDS_PACKED));
    return dicewareWords;
  }
  /* wordlist-codec:end */

  var CHARSET_UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  var CHARSET_LOWER = "abcdefghijklmnopqrstuvwxyz";
  var CHARSET_NUMBERS = "0123456789";
  var CHARSET_SYMBOLS = "!@#$%^&*()_+-=[]{}|;:,.<>?";
  var AMBIGUOUS = /[0O1lI|]/g;

  var currentMode = "random";

  /* Cryptographically uniform integer generation using 32-bit rejection sampling */
  function getSecureRandomInt(max) {
    var range = 0x100000000;
    var limit = range - (range % max);
    var array = new Uint32Array(1);
    do {
      window.crypto.getRandomValues(array);
    } while (array[0] >= limit);
    return array[0] % max;
  }

  function generateRandomPassword(length, useUpper, useLower, useNumbers, useSymbols, excludeAmbiguous) {
    var pool = "";
    if (useUpper) pool += CHARSET_UPPER;
    if (useLower) pool += CHARSET_LOWER;
    if (useNumbers) pool += CHARSET_NUMBERS;
    if (useSymbols) pool += CHARSET_SYMBOLS;

    if (excludeAmbiguous) {
      pool = pool.replace(AMBIGUOUS, "");
    }

    if (pool.length === 0) pool = CHARSET_LOWER;

    var password = "";
    var poolLen = pool.length;
    for (var i = 0; i < length; i++) {
      password += pool.charAt(getSecureRandomInt(poolLen));
    }
    return { password: password, poolSize: poolLen };
  }

  function generateDiceware(wordCount) {
    var words = [];
    var wordlist = getDicewareWords();
    var totalWords = wordlist.length;
    for (var i = 0; i < wordCount; i++) {
      words.push(wordlist[getSecureRandomInt(totalWords)]);
    }
    return { password: words.join("-"), poolSize: totalWords, wordCount: wordCount };
  }

  function generateQuantumKDF(length) {
    var chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!#$%&()*+,-./:;<=>?@[]^_{|}~";
    var result = "";
    var charsLen = chars.length;
    for (var i = 0; i < length; i++) {
      result += chars.charAt(getSecureRandomInt(charsLen));
    }
    return { password: result, poolSize: charsLen };
  }

  function generateHoneywords(masterPassword, count, useUpper, useLower, useNumbers, useSymbols, excludeAmbiguous) {
    var honeywords = [masterPassword];
    var len = masterPassword.length;
    for (var i = 0; i < count - 1; i++) {
      var fake = generateRandomPassword(len, useUpper, useLower, useNumbers, useSymbols, excludeAmbiguous).password;
      honeywords.push(fake);
    }
    for (var j = honeywords.length - 1; j > 0; j--) {
      var k = getSecureRandomInt(j + 1);
      var temp = honeywords[j];
      honeywords[j] = honeywords[k];
      honeywords[k] = temp;
    }
    return honeywords;
  }

  function calculateShannonEntropy(result, mode) {
    if (!result || !result.password) return 0;
    if (mode === "diceware") {
      var wordCount = result.wordCount || result.password.split("-").length;
      return Math.round(wordCount * Math.log2(WORDLIST_SIZE));
    }
    return Math.round(result.password.length * Math.log2(result.poolSize || 94));
  }

  /* Each table is [lower bound in bits, ...] in ascending order; the last
     row whose bound the entropy reaches applies. */
  var CRACK_TIMES = [[0, "Instant"], [40, "Few hours"], [60, "Centuries"], [80, "Cosmic Age"], [100, "Planetary Scale"], [120, "Quantum-Proof"]];
  var STRENGTHS = [[0, "weak", "Weak"], [50, "medium", "Moderate"], [80, "strong", "Strong"], [110, "quantum", "Quantum-Resistant"]];
  var SEGMENT_BITS = [35, 65, 90, 120, 140];
  /* {s} is the search-space size, {g} the Grover exponent. */
  var EXPLAINERS = [
    [0, "modern GPU cracking rigs (e.g. RTX 4090 clusters) can exhaust the {s} search space in seconds to minutes."],
    [50, "exhausting the {s} combinations requires centuries of compute time at 100 billion guesses per second."],
    [75, "the search space reaches {s}. Cracking requires millions of years, far outlasting recorded human civilization."],
    [105, "the search space expands to {s} combinations. Cracking energy exceeds the thermal output of planet Earth."],
    [135, "the search space exceeds {s} permutations. Under Grover's quantum search (quadratic speedup), effective search complexity remains at least 2<sup>{g}</sup> operations, maintaining cryptographic infeasibility."]
  ];

  function pickByEntropy(table, entropy) {
    var pick = table[0];
    for (var i = 1; i < table.length; i++) {
      if (entropy >= table[i][0]) pick = table[i];
    }
    return pick;
  }

  function setText(id, text) {
    var el = document.getElementById(id);
    if (el) el.textContent = text;
  }

  function setHtml(id, html) {
    var el = document.getElementById(id);
    if (el) el.innerHTML = html;
  }

  function updateSearchSpaceVisualizer(mode, length, poolSize, entropy, wordCount) {
    var effectiveLength = length;
    var effectivePool = poolSize;
    if (mode === "diceware") {
      effectiveLength = wordCount;
      effectivePool = WORDLIST_SIZE;
    } else if (mode === "quantum") {
      effectiveLength = Math.max(32, length);
    }

    var log10Total = effectiveLength * Math.log10(effectivePool);
    var exponent = Math.floor(log10Total);
    var mantissa = Math.pow(10, log10Total - exponent).toFixed(1);
    var power = mantissa + " × 10<sup>" + exponent + "</sup>";
    var poolLabel = mode === "diceware" ? "7,776" : String(effectivePool);
    setHtml("searchSpaceEquation", poolLabel + "<sup>" + effectiveLength + "</sup> ≈ " + power + " combinations");

    SEGMENT_BITS.forEach(function (bits, i) {
      var segment = document.getElementById("seg" + (i + 1));
      if (segment) segment.classList.toggle("is-active", entropy >= bits);
    });

    var unitLabel = mode === "diceware" ? " words" : " characters";
    var sentence = pickByEntropy(EXPLAINERS, entropy)[1]
      .replace("{s}", "~" + power)
      .replace("{g}", String(Math.floor(entropy / 2)));
    setHtml("searchSpaceExplainer", "At " + effectiveLength + unitLabel + " (" + entropy + " bits), " + sentence);
  }

  function readOptions() {
    var slider = document.getElementById("lengthSlider");
    function checked(id, fallback) {
      var box = document.getElementById(id);
      return box ? box.checked : fallback;
    }
    var length = slider ? parseInt(slider.value, 10) : 24;
    return {
      length: length,
      wordCount: Math.max(3, Math.min(12, Math.round(length / 4))),
      upper: checked("chkUpper", true),
      lower: checked("chkLower", true),
      numbers: checked("chkNumbers", true),
      symbols: checked("chkSymbols", true),
      ambiguous: checked("chkAmbiguous", false)
    };
  }

  function randomFor(opts, length) {
    return generateRandomPassword(length, opts.upper, opts.lower, opts.numbers, opts.symbols, opts.ambiguous);
  }

  function renderHoneywords(password, opts) {
    var box = document.getElementById("honeywordsBox");
    var list = document.getElementById("honeywordsList");
    if (!box) return;
    box.classList.remove("is-hidden");
    if (!list) return;
    var decoys = generateHoneywords(password, 5, opts.upper, opts.lower, opts.numbers, opts.symbols, opts.ambiguous);
    list.innerHTML = "";
    decoys.forEach(function (hw, idx) {
      var item = document.createElement("div");
      item.className = "honeyword-item";
      item.textContent = (idx + 1) + ". " + hw;
      list.appendChild(item);
    });
  }

  function generateForMode(opts) {
    if (currentMode === "diceware") return generateDiceware(opts.wordCount);
    if (currentMode === "quantum") return generateQuantumKDF(Math.max(32, opts.length));
    if (currentMode !== "random" && currentMode !== "honeywords") return { password: "", poolSize: 94 };
    var result = randomFor(opts, opts.length);
    if (currentMode === "honeywords") renderHoneywords(result.password, opts);
    return result;
  }

  function renderStrength(entropy) {
    var fill = document.getElementById("strengthFill");
    var label = document.getElementById("strengthLabel");
    if (!fill || !label) return;
    var band = pickByEntropy(STRENGTHS, entropy);
    fill.className = "strength-bar-fill strength-" + band[1];
    label.className = "strength-label text-" + band[1];
    label.textContent = band[2] + " (" + entropy + " bits)";
  }

  function refreshPassword() {
    var passwordOutput = document.getElementById("passwordOutput");
    if (!passwordOutput) return;
    var opts = readOptions();
    var diceware = currentMode === "diceware";
    setText("sliderLabel", diceware ? "Passphrase Length (Diceware Words)" : "Credential Length / Search Space");
    setText("lengthVal", diceware ? opts.wordCount + " words" : String(opts.length));

    var honeywordsBox = document.getElementById("honeywordsBox");
    if (honeywordsBox) honeywordsBox.classList.add("is-hidden");
    var result = generateForMode(opts);
    passwordOutput.textContent = result.password;

    var entropy = calculateShannonEntropy(result, currentMode);
    setHtml("valEntropy", entropy + " <small>bits</small>");
    setText("valPool", diceware ? "7,776 words" : result.poolSize + " chars");
    setText("valCrackTime", pickByEntropy(CRACK_TIMES, entropy)[1]);
    updateSearchSpaceVisualizer(currentMode, opts.length, result.poolSize, entropy, opts.wordCount);
    renderStrength(entropy);
  }

  function announceLive(message) {
    var region = document.getElementById("liveAnnouncement");
    if (region) {
      region.textContent = message;
      setTimeout(function () {
        region.textContent = "";
      }, 3000);
    }
  }

  function copyTextToClipboard(text, onDone, onFail) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(onDone).catch(function () {
        fallbackCopy(text, onDone, onFail);
      });
    } else {
      fallbackCopy(text, onDone, onFail);
    }
  }

  function fallbackCopy(text, onDone, onFail) {
    try {
      var textarea = document.createElement("textarea");
      textarea.value = text;
      textarea.setAttribute("readonly", "");
      textarea.style.position = "absolute";
      textarea.style.left = "-9999px";
      document.body.appendChild(textarea);
      textarea.select();
      var successful = document.execCommand("copy");
      document.body.removeChild(textarea);
      if (successful && onDone) onDone();
      else if (onFail) onFail();
    } catch (e) {
      if (onFail) onFail();
    }
  }

  /* Copies `text` and flashes "Copied!" on the button for two seconds. */
  function copyWithFeedback(button, text, iconSize, messages) {
    copyTextToClipboard(
      text,
      function () {
        var origHtml = button.innerHTML;
        button.classList.add("is-copied");
        button.innerHTML = '<svg width="' + iconSize + '" height="' + iconSize + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><polyline points="20 6 9 17 4 12"/></svg><span>Copied!</span>';
        announceLive(messages[0]);
        setTimeout(function () {
          button.classList.remove("is-copied");
          button.innerHTML = origHtml;
        }, 2000);
      },
      function () {
        announceLive(messages[1]);
      }
    );
  }

  function copyToClipboard() {
    var passwordOutput = document.getElementById("passwordOutput");
    var btnCopy = document.getElementById("btnCopy");
    if (!passwordOutput || !btnCopy) return;
    var pwd = passwordOutput.textContent;
    if (!pwd || pwd === "Generating...") return;
    copyWithFeedback(btnCopy, pwd, 16, ["Password copied to clipboard.", "Unable to copy password automatically."]);
  }

  function on(id, type, handler) {
    var el = document.getElementById(id);
    if (el) el.addEventListener(type, handler);
  }

  function bindTabs() {
    var tabs = document.querySelectorAll(".generator-tabs .tab-btn");
    tabs.forEach(function (tab) {
      tab.addEventListener("click", function () {
        tabs.forEach(function (t) {
          t.classList.remove("active");
          t.setAttribute("aria-selected", "false");
        });
        tab.classList.add("active");
        tab.setAttribute("aria-selected", "true");
        currentMode = tab.getAttribute("data-mode");
        refreshPassword();
      });
    });
  }

  function selectTabByHash() {
    var hash = window.location.hash;
    if (!hash || hash.indexOf("#tab-") !== 0) return;
    var targetTab = document.querySelector(hash);
    if (targetTab && targetTab.classList.contains("tab-btn")) targetTab.click();
  }

  /* DOM Init */
  document.addEventListener("DOMContentLoaded", function () {
    bindTabs();
    on("lengthSlider", "input", refreshPassword);
    document.querySelectorAll('.controls-grid input[type="checkbox"]').forEach(function (chk) {
      chk.addEventListener("change", refreshPassword);
    });
    on("btnRefresh", "click", refreshPassword);
    on("btnCopy", "click", copyToClipboard);
    on("btnCopyCli", "click", function () {
      copyWithFeedback(document.getElementById("btnCopyCli"), "npx jspassgen --length 32 --symbols", 13, ["Terminal command copied to clipboard.", "Unable to copy CLI command."]);
    });
    window.addEventListener("hashchange", selectTabByHash);
    refreshPassword();
    selectTabByHash();
  });
})();
